-- Backend Engineering ("The Fracture") Act 24 -- "Search Systems" content.
-- Closes Arc V ("Protect & Prove"). 1 campaign, 2 operations, 12 missions
-- (11 lessons + boss), following the campaigns -> operations -> missions ->
-- dialogue -> objectives -> challenges -> hints pattern. Uses the newer
-- slug-based id scheme (world-be-search already exists as a spine row).

insert into public.campaigns (id, world_id, slug, title, description, sort_order) values
  ('campaign-be-search', 'world-be-search', 'search-systems', '24A - Search Systems', 'A caseworker''s misspelled-name search returns nothing from a four-second database query, while the record it needed has sat in the registry the entire time. Learn what a real search engine does that a database was never built for -- and where the copy it keeps can quietly stop telling the truth.', 1);

insert into public.operations (id, campaign_id, slug, title, description, sort_order) values
  ('operation-be-search-1', 'campaign-be-search', 'the-slow-query', 'The Slow Query', 'Why database search breaks down, and the index structure a real search engine builds instead.', 1),
  ('operation-be-search-2', 'campaign-be-search', 'making-it-findable', 'Making It Findable', 'Turning a raw index into search that is fast, relevant, filterable, and honest about whether it is still in sync.', 2);

insert into public.missions (
  id, world_id, campaign_id, operation_id, slug, title, description, difficulty,
  character_ids, prerequisites, required_skills, lab, rewards, is_boss, sort_order
) values
  ('mission-be-search-01', 'world-be-search', 'campaign-be-search', 'operation-be-search-1', 'database-search-vs-search-engine', 'Database Search vs Search Engine', 'A caseworker types a misspelled name into the registry search and waits four seconds for zero results -- while the record they need has been sitting in the table the entire time.', 'advanced', ARRAY['mira','forge'], null, null, '{"type":"simulation","simulationId":"db-search-vs-engine-sim"}'::jsonb, '{"xp":245,"credits":48}'::jsonb, false, 1),
  ('mission-be-search-02', 'world-be-search', 'campaign-be-search', 'operation-be-search-1', 'the-inverted-index', 'Inverted Index', 'The single structure that makes real search fast: instead of scanning every row for a match, look the term up first and find out instantly which documents already have it.', 'advanced', ARRAY['forge'], '{"requiredMissionIds":["mission-be-search-01"]}'::jsonb, null, '{"type":"simulation","simulationId":"inverted-index-sim"}'::jsonb, '{"xp":246,"credits":48}'::jsonb, false, 2),
  ('mission-be-search-03', 'world-be-search', 'campaign-be-search', 'operation-be-search-1', 'elasticsearch-and-opensearch-concepts', 'Elasticsearch/OpenSearch Concepts', 'A search engine is its own database, with its own vocabulary -- clusters, nodes, indices and shards -- and its own reasons for existing next to PostgreSQL, not instead of it.', 'advanced', ARRAY['mira'], '{"requiredMissionIds":["mission-be-search-02"]}'::jsonb, null, '{"type":"simulation","simulationId":"es-concepts-sim"}'::jsonb, '{"xp":248,"credits":49}'::jsonb, false, 3),
  ('mission-be-search-04', 'world-be-search', 'campaign-be-search', 'operation-be-search-1', 'documents-and-mappings', 'Documents and Mappings', 'Elasticsearch does not store rows -- it stores documents, and a mapping is the schema that decides how each field inside one actually gets indexed and searched.', 'advanced', ARRAY['forge'], '{"requiredMissionIds":["mission-be-search-03"]}'::jsonb, null, '{"type":"simulation","simulationId":"documents-mappings-sim"}'::jsonb, '{"xp":249,"credits":49}'::jsonb, false, 4),
  ('mission-be-search-05', 'world-be-search', 'campaign-be-search', 'operation-be-search-1', 'analyzers', 'Analyzers', 'Text is never indexed exactly as typed. An analyzer is the pipeline that decides what a search term is even allowed to match.', 'advanced', ARRAY['mira'], '{"requiredMissionIds":["mission-be-search-04"]}'::jsonb, null, '{"type":"simulation","simulationId":"analyzers-sim"}'::jsonb, '{"xp":250,"credits":49}'::jsonb, false, 5),
  ('mission-be-search-06', 'world-be-search', 'campaign-be-search', 'operation-be-search-1', 'tokenization', 'Tokenization', 'The one stage inside every analyzer that actually splits text into searchable pieces -- and the exact place a hyphenated or differently-spaced name can quietly stop being findable.', 'advanced', ARRAY['forge'], '{"requiredMissionIds":["mission-be-search-05"]}'::jsonb, null, '{"type":"simulation","simulationId":"tokenization-sim"}'::jsonb, '{"xp":250,"credits":50}'::jsonb, false, 6),
  ('mission-be-search-07', 'world-be-search', 'campaign-be-search', 'operation-be-search-2', 'full-text-search', 'Full-Text Search', 'The query type the registry never had: ranked, typo-tolerant matches across real language, instead of one literal substring check.', 'advanced', ARRAY['mira','forge'], '{"requiredMissionIds":["mission-be-search-06"]}'::jsonb, null, '{"type":"simulation","simulationId":"full-text-search-sim"}'::jsonb, '{"xp":252,"credits":50}'::jsonb, false, 7),
  ('mission-be-search-08', 'world-be-search', 'campaign-be-search', 'operation-be-search-2', 'relevance', 'Relevance', 'Full-text search does not just find matches, it ranks them. Relevance scoring is the reason the right record can surface first even when it is not the closest exact spelling.', 'advanced', ARRAY['mira'], '{"requiredMissionIds":["mission-be-search-07"]}'::jsonb, null, '{"type":"simulation","simulationId":"relevance-sim"}'::jsonb, '{"xp":253,"credits":50}'::jsonb, false, 8),
  ('mission-be-search-09', 'world-be-search', 'campaign-be-search', 'operation-be-search-2', 'filters', 'Filters', 'Not every condition should affect ranking. A filter narrows results without scoring them -- and skips relevance math a plain query would run whether it mattered or not.', 'advanced', ARRAY['forge'], '{"requiredMissionIds":["mission-be-search-08"]}'::jsonb, null, '{"type":"simulation","simulationId":"filters-sim"}'::jsonb, '{"xp":254,"credits":51}'::jsonb, false, 9),
  ('mission-be-search-10', 'world-be-search', 'campaign-be-search', 'operation-be-search-2', 'autocomplete', 'Autocomplete', 'Search-as-you-type needs an index built for partial input, not a whole word entered and confirmed -- a different shape entirely from what you have been querying all Act.', 'advanced', ARRAY['mira'], '{"requiredMissionIds":["mission-be-search-09"]}'::jsonb, null, '{"type":"simulation","simulationId":"autocomplete-sim"}'::jsonb, '{"xp":255,"credits":51}'::jsonb, false, 10),
  ('mission-be-search-11', 'world-be-search', 'campaign-be-search', 'operation-be-search-2', 'search-index-synchronization', 'Search Index Synchronization', 'A search index is a copy, not a source of truth -- and the moment something writes to the real database without telling the index, the two quietly start disagreeing about what exists.', 'advanced', ARRAY['mira','forge'], '{"requiredMissionIds":["mission-be-search-10"]}'::jsonb, null, '{"type":"simulation","simulationId":"index-sync-sim"}'::jsonb, '{"xp":258,"credits":52}'::jsonb, false, 11),
  ('mission-be-search-12', 'world-be-search', 'campaign-be-search', 'operation-be-search-2', 'find-one-citizen-in-a-billion-records', 'Find One Citizen in a Billion Records', 'The first full backfill of the citizen registry into the search index turns up records that were never searchable at all -- and an unsettling share of them carry one particular tag.', 'boss', ARRAY['mira','forge'], '{"requiredMissionIds":["mission-be-search-11"]}'::jsonb, null, '{"type":"simulation","simulationId":"find-one-citizen-boss-sim"}'::jsonb, '{"xp":570,"credits":132,"badgeIds":["find-one-citizen"],"skillXp":{"search_systems":30}}'::jsonb, true, 12);

insert into public.dialogue_lines (mission_id, sort_order, character_id, text) values
  ('mission-be-search-01', 1, 'mira', 'A caseworker typed ''Katarzyna Wozniack'' into the registry search -- one letter off from the real spelling -- and got zero results in four seconds. The record she needed has been sitting in the table the entire time.'),
  ('mission-be-search-01', 2, 'forge', 'That is not a bug. That is exactly what a WHERE full_name LIKE query is built to do: scan every row, compare the string literally, and give up the instant it does not match exactly.'),
  ('mission-be-search-01', 3, 'mira', 'A relational database is built to store facts precisely and answer precise questions fast. It was never built to guess what someone meant. That is a different tool, and right now we do not have it running.'),
  ('mission-be-search-02', 1, 'forge', 'Here is the trick every real search engine relies on: instead of scanning every document to see if a term is inside it, build the answer in advance. For every term, keep a list of every document that contains it.'),
  ('mission-be-search-02', 2, 'forge', 'That list is called a postings list, and the whole structure -- term to documents, instead of document to terms -- is an inverted index. Look up ''wozniak'' once, get every matching document instantly, no scan required.'),
  ('mission-be-search-03', 1, 'mira', 'Elasticsearch, and its open-source fork OpenSearch, are what we are standing up next to PostgreSQL -- not instead of it. Different job, different guarantees.'),
  ('mission-be-search-03', 2, 'mira', 'A cluster is the whole deployment. It is made of nodes, individual running servers. Data lives in indices, and each index is split into shards so it can scale past what one node could hold or search alone.'),
  ('mission-be-search-03', 3, 'forge', 'PostgreSQL stays the source of truth for the registry. Elasticsearch becomes a purpose-built copy, shaped entirely around being searched, not just stored.'),
  ('mission-be-search-04', 1, 'forge', 'Elasticsearch does not think in rows. It thinks in documents -- one JSON object per citizen, self-contained, not spread across foreign-keyed tables.'),
  ('mission-be-search-04', 2, 'forge', 'A mapping is the part that matters most: it is the schema that says, for every field in that document, how it should be indexed -- exact-match text, full-text-searchable prose, a number, a date. Get a field''s mapping wrong and no query will ever find it the way you expect.'),
  ('mission-be-search-05', 1, 'mira', 'Before any document is stored, its text passes through an analyzer. Nothing gets indexed exactly as typed -- an analyzer decides what a term is even allowed to look like once it is searchable.'),
  ('mission-be-search-05', 2, 'mira', 'Every analyzer is a pipeline: an optional character filter, then a tokenizer, then zero or more token filters. Each stage reshapes the text a little more before it becomes something a query can actually match against.'),
  ('mission-be-search-06', 1, 'forge', 'Tokenization is the one stage in that pipeline that actually splits text into pieces. ''Katarzyna Wozniak'' becomes two tokens: ''katarzyna'' and ''wozniak.'' Get the tokenizer wrong for a name with a hyphen or unusual spacing, and it can split somewhere that quietly makes the name unfindable.'),
  ('mission-be-search-06', 2, 'forge', 'The original misspelled search was not only about the typo. It is also about whether the tokenizer sitting in front of the query was ever built with names like this one in mind.'),
  ('mission-be-search-07', 1, 'mira', 'This is the query type the registry never had: full-text search. Instead of demanding an exact string match, it tokenizes your search terms the same way it tokenized the documents, and returns every document that matches well enough -- ranked, not just found.'),
  ('mission-be-search-07', 2, 'forge', 'match instead of equals. term instead of exact string. It is a completely different question than the one a WHERE clause knows how to ask.'),
  ('mission-be-search-08', 1, 'mira', 'Full-text search does not stop at ''does this match.'' It scores every match and ranks the results -- that score is relevance, and it is the reason the record you actually want can land first even when it is not the closest string.'),
  ('mission-be-search-08', 2, 'mira', 'Term frequency, inverse document frequency, field length -- a relevance algorithm like BM25 combines all of it into one number per document. A rare term matching is worth more than a common one matching, and a short field matching means more than the same term buried in a long one.'),
  ('mission-be-search-09', 1, 'forge', 'Not every condition you care about should move the relevance score. ''Is this citizen active'' is not a matter of degree -- it is yes or no. That belongs in a filter, not a scored query.'),
  ('mission-be-search-09', 2, 'forge', 'Filters run in a separate context: no scoring math, and the engine can cache the result. Put a yes/no condition inside a scored query and you are paying for relevance math on a question that never needed it.'),
  ('mission-be-search-10', 1, 'mira', 'A caseworker typing ''Woz'' and expecting suggestions before she finishes the name needs a completely different index shape -- one built on partial input, not whole confirmed words.'),
  ('mission-be-search-10', 2, 'mira', 'Edge n-grams index every prefix of a term as its own token, so ''wozniak'' is also searchable as ''w'', ''wo'', ''woz'', ''wozn.'' Autocomplete against that index, and every keystroke can return real matches.'),
  ('mission-be-search-11', 1, 'forge', 'Here is the part nobody warns you about until it bites: Elasticsearch does not know a citizen record changed in PostgreSQL unless something tells it. The index is not the source of truth. It is a copy, and copies drift.'),
  ('mission-be-search-11', 2, 'mira', 'A citizen updated, or created, in the real database does not exist in the search index until some process re-indexes it. Until then, search behaves as if that citizen does not exist at all. Not wrong. Worse -- confidently, silently incomplete.'),
  ('mission-be-search-12', 1, 'mira', 'First real backfill of the citizen registry into the search index. Every record, indexed for the first time, ever.'),
  ('mission-be-search-12', 2, 'forge', 'Backfill is done. And it surfaced something: a set of records that exist in PostgreSQL, have existed for a while, and had never once been indexed -- meaning never once searchable, by anyone, until right now.'),
  ('mission-be-search-12', 3, 'mira', 'How many, and what do they have in common?'),
  ('mission-be-search-12', 4, 'forge', 'Small percentage of the total registry. But look at what they share: a disproportionate share carry that trailing ''//'' tag we have been logging since Act 2. Not most records with the tag overall -- most of the never-indexed records, specifically.'),
  ('mission-be-search-12', 5, 'mira', 'Say that again, slower.'),
  ('mission-be-search-12', 6, 'forge', 'Records tagged ''//'' are not just slightly more likely to be missing from search. They are the largest single group inside the ''never indexed at all'' set. As if whatever writes that tag has been avoiding, specifically, the one path that would have made those records findable.'),
  ('mission-be-search-12', 7, 'mira', 'We are not saying that is deliberate. We do not have enough to say that, and I will not let anyone write that conclusion into a report tonight. What we can say, and only this: the pattern is real, it is reproducible, and it correlates with something that makes findability worse, not with something neutral.'),
  ('mission-be-search-12', 8, 'forge', 'Noted. Filed. Same as always -- we watch it, we do not chase a ghost off one correlation.'),
  ('mission-be-search-12', 9, 'mira', 'Fix the sync gap first. That is the job in front of us. The rest keeps waiting -- it has waited this long already.');

insert into public.objectives (id, mission_id, sort_order, title, description) values
  ('mission-be-search-01-o1', 'mission-be-search-01', 1, 'Diagnose the slow query', 'Find the evidence that explains why the caseworker''s search was never going to succeed, no matter how long it ran.'),
  ('mission-be-search-01-o2', 'mission-be-search-01', 2, 'Name the mismatch', 'Explain why a plain LIKE query is the wrong long-term tool even with perfect spelling.'),
  ('mission-be-search-02-o1', 'mission-be-search-02', 1, 'Understand the index', 'Explain why an inverted index makes a term lookup fast across a huge document set.'),
  ('mission-be-search-02-o2', 'mission-be-search-02', 2, 'Build the postings list', 'Sort documents into whether they actually belong in the postings list for the term ''wozniak''.'),
  ('mission-be-search-03-o1', 'mission-be-search-03', 1, 'Learn the vocabulary', 'Match each Elasticsearch/OpenSearch term to what it actually means.'),
  ('mission-be-search-03-o2', 'mission-be-search-03', 2, 'Justify the second system', 'Explain why a separate search engine exists alongside PostgreSQL instead of replacing it.'),
  ('mission-be-search-04-o1', 'mission-be-search-04', 1, 'Find the broken mapping', 'Identify the field mapping that would break free-text search on a name.'),
  ('mission-be-search-05-o1', 'mission-be-search-05', 1, 'Order the pipeline', 'Put the three stages of an analyzer pipeline in the order text actually passes through them.'),
  ('mission-be-search-05-o2', 'mission-be-search-05', 2, 'Explain the token filter', 'Explain why lowercasing and stopword removal matter for search, not just storage.'),
  ('mission-be-search-06-o1', 'mission-be-search-06', 1, 'Find the tokenization gap', 'Find the evidence that explains why the same name can be found with one spacing and missed with another.'),
  ('mission-be-search-07-o1', 'mission-be-search-07', 1, 'Match vs LIKE', 'Explain what actually separates a match query from a LIKE query on the same field.'),
  ('mission-be-search-07-o2', 'mission-be-search-07', 2, 'Find the query that works', 'Find the evidence that shows why a full-text match, not an exact term match, is what finally finds the misspelled name.'),
  ('mission-be-search-08-o1', 'mission-be-search-08', 1, 'Match the scoring factors', 'Match each relevance-scoring concept to what it actually measures.'),
  ('mission-be-search-08-o2', 'mission-be-search-08', 2, 'Explain the ranking', 'Find the evidence that explains why one matching document legitimately outranks another.'),
  ('mission-be-search-09-o1', 'mission-be-search-09', 1, 'Find the misplaced clause', 'Identify the condition that should never influence the relevance score.'),
  ('mission-be-search-10-o1', 'mission-be-search-10', 1, 'Explain autocomplete', 'Explain what actually has to change in the index for search-as-you-type to work.'),
  ('mission-be-search-11-o1', 'mission-be-search-11', 1, 'Find the stale record', 'Find the evidence that explains why a search result is stale even though the real record was updated recently.'),
  ('mission-be-search-11-o2', 'mission-be-search-11', 2, 'State the real relationship', 'State the correct relationship between PostgreSQL and the search index.'),
  ('mission-be-search-12-o1', 'mission-be-search-12', 1, 'Read the backfill', 'Find the evidence that establishes the actual pattern worth escalating.'),
  ('mission-be-search-12-o2', 'mission-be-search-12', 2, 'Diagnose the sync gap', 'Explain why a record that existed in PostgreSQL for months only became searchable during the backfill.'),
  ('mission-be-search-12-o3', 'mission-be-search-12', 3, 'Choose the real fix', 'Choose the fix that actually closes the sync gap going forward, not just for the records already caught.'),
  ('mission-be-search-12-o4', 'mission-be-search-12', 4, 'Close the case', 'Synthesize the backfill evidence, the sync diagnosis and the fix into one closing report.');

insert into public.challenges (id, objective_id, sort_order, type, prompt, content, completion_conditions) values
  ('mission-be-search-01-o1-c1', 'mission-be-search-01-o1', 1, 'investigation', 'Which piece of evidence explains why the record was never going to be found by this query, no matter how long it ran?', '{"evidence":[{"id":"ev1","label":"Search query executed","detail":"SELECT * FROM citizens WHERE full_name ILIKE ''''%Wozniack%''''; -- 0 rows, 4.1s"},{"id":"ev2","label":"Actual registry row","detail":"citizen_id 88213, full_name ''''Wozniak, Katarzyna'''' -- present in the table the entire time"},{"id":"ev3","label":"Query plan","detail":"Seq Scan on citizens (cost=0.00..48213.00 rows=1) -- every row read and string-compared, no index used"}],"question":"Which piece of evidence explains why the record was never going to be found by this query, no matter how long it ran?"}'::jsonb, '{"requiredEvidenceIds":["ev2"]}'::jsonb),
  ('mission-be-search-01-o2-c1', 'mission-be-search-01-o2', 1, 'multiple_choice', 'Even with perfect spelling, why is a plain LIKE query the wrong long-term tool for this kind of search?', '{"question":"The caseworker''''s misspelling is one problem. But even with perfect spelling, why is a plain LIKE query the wrong long-term tool for this kind of search?","options":[{"id":"a","text":"LIKE queries can only be run by administrators"},{"id":"b","text":"A LIKE/ILIKE scan compares the literal string against every row with no ranking, no relevance and no understanding of language -- it can only ever answer ''''does this exact substring appear,'''' never ''''what did the user probably mean''''"},{"id":"c","text":"PostgreSQL does not actually support the LIKE keyword"},{"id":"d","text":"LIKE queries always return every row in the table"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),

  ('mission-be-search-02-o1-c1', 'mission-be-search-02-o1', 1, 'multiple_choice', 'Why does an inverted index make a search for ''wozniak'' fast across a billion documents?', '{"question":"An inverted index stores, for every unique term, a list of every document containing it -- a postings list. Why does that make a search for ''''wozniak'''' fast across a billion documents?","options":[{"id":"a","text":"It does not -- it still has to scan every document"},{"id":"b","text":"Because looking up one term''''s postings list is a direct lookup, not a scan -- the work is proportional to how many documents actually contain the term, not how many documents exist"},{"id":"c","text":"Because it stores documents in alphabetical order by content"},{"id":"d","text":"Because it deletes every document that does not match common terms"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),
  ('mission-be-search-02-o2-c1', 'mission-be-search-02-o2', 1, 'drag_and_drop', 'Sort each document into whether it actually belongs in the postings list for the term ''wozniak''.', '{"items":[{"id":"i1","text":"Doc 41: \"Katarzyna Wozniak, unit 12\" -- tokenizes to include the token wozniak"},{"id":"i2","text":"Doc 55: \"Marcus Owusu, unit 4\" -- no occurrence of wozniak at all"},{"id":"i3","text":"Doc 60: \"Wozniak Logistics annual filing\" -- tokenizes to include the token wozniak"},{"id":"i4","text":"Doc 71: \"Ana Wozniakowski, unit 9\" -- tokenizes to a single token wozniakowski, distinct from wozniak"}],"targets":[{"id":"t1","label":"In the postings list for term \"wozniak\""},{"id":"t2","label":"Not in that postings list"}]}'::jsonb, '{"correctMapping":{"i1":"t1","i2":"t2","i3":"t1","i4":"t2"}}'::jsonb),

  ('mission-be-search-03-o1-c1', 'mission-be-search-03-o1', 1, 'drag_and_drop', 'Match each term to what it actually means.', '{"items":[{"id":"c1","text":"Cluster"},{"id":"c2","text":"Node"},{"id":"c3","text":"Index"},{"id":"c4","text":"Shard"},{"id":"c5","text":"Document"}],"targets":[{"id":"t1","label":"The entire deployment -- every node working together"},{"id":"t2","label":"One running instance of Elasticsearch/OpenSearch, usually one server"},{"id":"t3","label":"The equivalent of a table -- a named collection of similar documents"},{"id":"t4","label":"A horizontal slice of an index, so it can be spread across multiple nodes"},{"id":"t5","label":"One JSON record -- the equivalent of a row"}]}'::jsonb, '{"correctMapping":{"c1":"t1","c2":"t2","c3":"t3","c4":"t4","c5":"t5"}}'::jsonb),
  ('mission-be-search-03-o2-c1', 'mission-be-search-03-o2', 1, 'multiple_choice', 'Why stand up a separate Elasticsearch cluster instead of just building a better index inside PostgreSQL?', '{"question":"PostgreSQL already stores every citizen record. Why stand up an entirely separate Elasticsearch cluster instead of just building a better index inside PostgreSQL?","options":[{"id":"a","text":"PostgreSQL cannot store text at all"},{"id":"b","text":"Elasticsearch is purpose-built for full-text relevance ranking, typo tolerance and horizontal scaling of search itself -- capabilities a general-purpose relational database was not designed around, even though it can do basic full-text indexing"},{"id":"c","text":"Elasticsearch is meant to fully replace PostgreSQL"},{"id":"d","text":"Elasticsearch is required before PostgreSQL can accept any writes"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),

  ('mission-be-search-04-o1-c1', 'mission-be-search-04-o1', 1, 'code_debugging', 'This mapping makes free-text search on full_name return nothing unless the query matches the entire field exactly. Which line causes that?', '{"language":"json","code":"{\n  \"mappings\": {\n    \"properties\": {\n      \"citizen_id\": { \"type\": \"integer\" },\n      \"full_name\": { \"type\": \"keyword\" },\n      \"date_of_birth\": { \"type\": \"date\" },\n      \"tag\": { \"type\": \"keyword\" }\n    }\n  }\n}","question":"This mapping makes free-text search on full_name return nothing unless the query matches the entire field exactly, character for character. Which line causes that?"}'::jsonb, '{"requiredLineIds":["      \"full_name\": { \"type\": \"keyword\" },"]}'::jsonb),

  ('mission-be-search-05-o1-c1', 'mission-be-search-05-o1', 1, 'interactive_diagram', 'Put the three stages of an analyzer pipeline in the order text actually passes through them.', '{"diagramId":"analyzer-pipeline","hotspots":[{"id":"char_filter","label":"Character filter","explanation":"Runs first, and is optional -- strips or replaces raw characters before anything else sees the text, such as stripping HTML tags."},{"id":"tokenizer","label":"Tokenizer","explanation":"Splits the (possibly cleaned) text into individual tokens -- this is the one mandatory stage."},{"id":"token_filter","label":"Token filter","explanation":"Runs last, zero or more times -- reshapes individual tokens, such as lowercasing or removing stopwords."}],"task":"Put the three stages of an analyzer pipeline in the order text actually passes through them."}'::jsonb, '{"correctOrderIds":["char_filter","tokenizer","token_filter"]}'::jsonb),
  ('mission-be-search-05-o2-c1', 'mission-be-search-05-o2', 1, 'multiple_choice', 'Why does a token filter that lowercases and strips stopwords matter for search?', '{"question":"A token filter lowercases every token and strips common words like ''''the'''' and ''''and.'''' Why does that matter for search?","options":[{"id":"a","text":"It only makes the index smaller, which is the sole benefit"},{"id":"b","text":"It lets ''''Wozniak'''' and ''''wozniak'''' match the same query, and keeps near-meaningless words from diluting relevance scoring -- without it, case and stopwords would silently break matches users expect to work"},{"id":"c","text":"It deletes every document containing those words"},{"id":"d","text":"It has no effect on search results, only on storage size"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),

  ('mission-be-search-06-o1-c1', 'mission-be-search-06-o1', 1, 'investigation', 'Which piece of evidence explains why the same person''s name can be found with one spacing and missed with another, using the same tokenizer the whole time?', '{"evidence":[{"id":"ev1","label":"Stored document","detail":"full_name: ''''Anne-Marie Kowalczyk'''' -- standard tokenizer splits it into [''''anne'''', ''''marie'''', ''''kowalczyk'''']"},{"id":"ev2","label":"Caseworker query A","detail":"Typed ''''Anne-Marie'''' -- tokenized into [''''anne'''', ''''marie''''] -- matches, record found"},{"id":"ev3","label":"Caseworker query B","detail":"Typed ''''Annemarie'''' with no hyphen or space -- tokenized into a single token [''''annemarie''''], which matches neither stored token -- record not found"}],"question":"Which piece of evidence explains why the same person''''s name can be found with one spacing and missed with another, using the same tokenizer the whole time?"}'::jsonb, '{"requiredEvidenceIds":["ev3"]}'::jsonb),

  ('mission-be-search-07-o1-c1', 'mission-be-search-07-o1', 1, 'multiple_choice', 'What actually separates a match query from a LIKE query on the same field?', '{"question":"The registry''''s old query used WHERE full_name LIKE. What is the actual difference between that and an Elasticsearch match query on the same field?","options":[{"id":"a","text":"match tokenizes the query the same way the field was analyzed, then finds documents sharing any of those tokens, ranked by how well they match -- LIKE only ever checks for one literal substring"},{"id":"b","text":"match and LIKE do exactly the same thing, just with different syntax"},{"id":"c","text":"match only works on numeric fields"},{"id":"d","text":"LIKE is faster because it uses relevance scoring"}]}'::jsonb, '{"correctOptionId":"a"}'::jsonb),
  ('mission-be-search-07-o2-c1', 'mission-be-search-07-o2', 1, 'investigation', 'Which piece of evidence shows why a full-text match query, not a term query, is what finally finds the misspelled name?', '{"evidence":[{"id":"ev1","label":"Query used","detail":"A match query on full_name with fuzziness: \"AUTO\", tolerating a one- or two-character edit distance"},{"id":"ev2","label":"Same query, misspelled input","detail":"Search term ''''Wozniack'''' still returns ''''Wozniak, Katarzyna'''' as the top result"},{"id":"ev3","label":"term query attempt","detail":"A term query -- exact, unanalyzed match -- on the same field with the same misspelled input returns zero results"}],"question":"Which piece of evidence shows why a full-text match query, not an exact term query, is what finally finds the misspelled name?"}'::jsonb, '{"requiredEvidenceIds":["ev2"]}'::jsonb),

  ('mission-be-search-08-o1-c1', 'mission-be-search-08-o1', 1, 'drag_and_drop', 'Match each relevance-scoring concept to what it actually measures.', '{"items":[{"id":"r1","text":"Term frequency (TF)"},{"id":"r2","text":"Inverse document frequency (IDF)"},{"id":"r3","text":"Field length norm"}],"targets":[{"id":"t1","label":"How often the search term appears in this one document -- more occurrences, higher score"},{"id":"t2","label":"How rare the search term is across the whole index -- a rare term matching counts for more than a common one"},{"id":"t3","label":"How long the field is -- a match in a short field scores higher than the same match buried in a long one"}]}'::jsonb, '{"correctMapping":{"r1":"t1","r2":"t2","r3":"t3"}}'::jsonb),
  ('mission-be-search-08-o2-c1', 'mission-be-search-08-o2', 1, 'investigation', 'Which evidence explains why one document legitimately outranks the other?', '{"evidence":[{"id":"ev1","label":"Result A score breakdown","detail":"full_name field: ''''Wozniak, Katarzyna'''' -- one short field, one clean match, score 8.2"},{"id":"ev2","label":"Result B score breakdown","detail":"notes field, 400 words long, contains ''''Wozniak'''' once among unrelated case notes -- score 1.1"},{"id":"ev3","label":"Record creation timestamps","detail":"Result A created 2019, Result B created 2024"}],"question":"Two documents both contain ''''Wozniak.'''' Which evidence explains why one legitimately outranks the other?"}'::jsonb, '{"requiredEvidenceIds":["ev1","ev2"]}'::jsonb),

  ('mission-be-search-09-o1-c1', 'mission-be-search-09-o1', 1, 'code_debugging', 'One of these two clauses should never influence the relevance score. Which line is it?', '{"language":"json","code":"{\n  \"query\": {\n    \"bool\": {\n      \"must\": [\n        { \"match\": { \"full_name\": \"Wozniak\" } },\n        { \"term\": { \"status\": \"active\" } }\n      ]\n    }\n  }\n}","question":"One of these two clauses is a plain yes/no condition, not a matter of degree, and should never influence the relevance score -- it belongs in a filter clause instead of must. Which line is it?"}'::jsonb, '{"requiredLineIds":["        { \"term\": { \"status\": \"active\" } }"]}'::jsonb),

  ('mission-be-search-10-o1-c1', 'mission-be-search-10-o1', 1, 'multiple_choice', 'Why can not the same full-text index used for finished searches serve live autocomplete directly?', '{"question":"A caseworker types ''''Woz'''' and expects live suggestions before finishing the name. Why can''''t the same full-text index used for finished searches serve that directly?","options":[{"id":"a","text":"It technically can, once every prefix of each term is also indexed ahead of time -- typically with edge n-grams or a completion suggester -- so a partial string like ''''Woz'''' is itself an indexed, matchable token"},{"id":"b","text":"Autocomplete is not possible in Elasticsearch at all"},{"id":"c","text":"It requires an entirely separate database, unrelated to search"},{"id":"d","text":"The full-text index already contains every prefix automatically, with no extra configuration needed"}]}'::jsonb, '{"correctOptionId":"a"}'::jsonb),

  ('mission-be-search-11-o1-c1', 'mission-be-search-11-o1', 1, 'investigation', 'Which piece of evidence explains why the search result is stale even though the real record was updated recently?', '{"evidence":[{"id":"ev1","label":"PostgreSQL row","detail":"citizen_id 88213, full_name updated to ''''Wozniak-Baran, Katarzyna'''' 40 minutes ago"},{"id":"ev2","label":"Elasticsearch document","detail":"citizen_id 88213 still shows full_name ''''Wozniak, Katarzyna'''' -- the update was never reflected"},{"id":"ev3","label":"Reindex job log","detail":"No reindex job has run against this citizen_id since it was first indexed, months ago"}],"question":"Which piece of evidence explains why the search result is stale even though the real record was updated 40 minutes ago?"}'::jsonb, '{"requiredEvidenceIds":["ev3"]}'::jsonb),
  ('mission-be-search-11-o2-c1', 'mission-be-search-11-o2', 1, 'multiple_choice', 'What is the actual right way to think about the relationship between PostgreSQL and Elasticsearch here?', '{"question":"Given that gap, what is the actual right way to think about the relationship between PostgreSQL and Elasticsearch here?","options":[{"id":"a","text":"They are two equally authoritative copies of the same data"},{"id":"b","text":"Elasticsearch is the source of truth, and PostgreSQL is the copy"},{"id":"c","text":"PostgreSQL is the source of truth; Elasticsearch is a copy shaped for search, and it is only ever as current as whatever process keeps it in sync"},{"id":"d","text":"There is no meaningful difference between the two once both contain the same record"}]}'::jsonb, '{"correctOptionId":"c"}'::jsonb),

  ('mission-be-search-12-o1-c1', 'mission-be-search-12-o1', 1, 'investigation', 'Which single piece of evidence establishes the actual pattern worth escalating -- not just a number, but a correlation?', '{"evidence":[{"id":"ev1","label":"Backfill summary","detail":"212,884 citizen records indexed for the first time; none of them previously existed in Elasticsearch under those ids"},{"id":"ev2","label":"Tag breakdown","detail":"Records carrying the trailing \"//\" tag are 1.8% of the full registry, but 34% of the records that had never been indexed at all"},{"id":"ev3","label":"Write timeline","detail":"Every never-indexed record was inserted or updated directly against PostgreSQL, with no reindex job ever recorded against its id"}],"question":"Which single piece of evidence establishes the actual pattern worth escalating -- not just a number, but a correlation?"}'::jsonb, '{"requiredEvidenceIds":["ev2"]}'::jsonb),
  ('mission-be-search-12-o2-c1', 'mission-be-search-12-o2', 1, 'multiple_choice', 'A citizen record was created in PostgreSQL months ago and only became searchable today. What actually explains that gap?', '{"question":"A citizen record was created in PostgreSQL months ago. It only became searchable today, during the backfill. What actually explains that gap?","options":[{"id":"a","text":"Elasticsearch was down for the entire period"},{"id":"b","text":"The search index is a copy of the data, not the source of truth -- nothing had ever told it this record existed, so it silently behaved as if the record did not"},{"id":"c","text":"PostgreSQL and Elasticsearch were never on the same network"},{"id":"d","text":"The citizen''''s record was corrupted inside PostgreSQL"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),
  ('mission-be-search-12-o3-c1', 'mission-be-search-12-o3', 1, 'multiple_choice', 'Which fix actually closes the sync gap for records created going forward, not just the ones this backfill already caught?', '{"question":"Now that the sync gap itself is understood, which fix actually closes it -- for records created going forward, not just the ones this backfill already caught?","options":[{"id":"a","text":"Re-run the same manual backfill script every time someone happens to notice a record missing"},{"id":"b","text":"Add a nightly cron job that re-indexes everything once a day"},{"id":"c","text":"Add change-data-capture, or an equivalent event-driven pipeline, that re-indexes a document the moment its row changes in PostgreSQL"},{"id":"d","text":"Tell caseworkers to also check PostgreSQL directly whenever search comes back empty"}]}'::jsonb, '{"correctOptionId":"c"}'::jsonb),
  ('mission-be-search-12-o4-c1', 'mission-be-search-12-o4', 1, 'boss_encounter', 'Having read the backfill evidence, diagnosed the sync gap and chosen the real fix, close the case.', '{"stages":[{"objectiveRef":"mission-be-search-12-o1","label":"Read the backfill"},{"objectiveRef":"mission-be-search-12-o2","label":"Diagnose the sync gap"},{"objectiveRef":"mission-be-search-12-o3","label":"Choose the real fix"}],"task":"Having read the backfill evidence, diagnosed the sync gap and chosen the real fix, state what actually has to change: search needs an event-driven re-index pipeline tied to every write, not a periodic guess -- and file, without concluding why, that records tagged \"//\" were a disproportionate share of everything that had never been searchable at all."}'::jsonb, '{"requiredObjectiveIds":["mission-be-search-12-o1","mission-be-search-12-o2","mission-be-search-12-o3"],"allCorrect":true}'::jsonb);

insert into public.hints (challenge_id, tier, text, xp_cost, sort_order) values
  ('mission-be-search-01-o1-c1', 'orientation', 'The query is looking for a literal substring. Compare what it was told to look for against what is actually stored.', 10, 1),
  ('mission-be-search-01-o1-c1', 'concept', 'ILIKE still requires the search string to appear, character for character, inside the stored value -- case-insensitive is not the same as typo-tolerant.', 20, 2),
  ('mission-be-search-01-o1-c1', 'solution', '''Wozniack'' is not a substring of ''Wozniak, Katarzyna'' -- the extra c means no literal match was ever possible, no matter how the query was tuned.', 30, 3),
  ('mission-be-search-01-o2-c1', 'orientation', 'Ask what a LIKE query fundamentally cannot do, even with the correct spelling typed in.', 10, 1),
  ('mission-be-search-01-o2-c1', 'solution', 'LIKE only ever answers a literal substring question -- no ranking, no fuzziness, no understanding of what the text actually means.', 20, 2),

  ('mission-be-search-02-o1-c1', 'orientation', 'Compare the cost of a lookup against the cost of a scan.', 10, 1),
  ('mission-be-search-02-o1-c1', 'solution', 'A postings list turns ''find every document with this term'' into a direct lookup, sized to the matches, not to the whole collection.', 20, 2),
  ('mission-be-search-02-o2-c1', 'orientation', 'Tokenization matters here -- a substring inside a word is not the same as a matching token.', 10, 1),
  ('mission-be-search-02-o2-c1', 'concept', '''Wozniakowski'' contains the letters w-o-z-n-i-a-k, but it tokenizes to one whole token, not to ''wozniak'' plus something else.', 20, 2),
  ('mission-be-search-02-o2-c1', 'solution', 'Doc 41 and Doc 60 both tokenize to include the exact token ''wozniak''. Doc 55 has no occurrence at all, and Doc 71 tokenizes to the distinct token ''wozniakowski''.', 30, 3),

  ('mission-be-search-03-o1-c1', 'orientation', 'Think in terms of scale, largest to smallest: the whole deployment, down to one record.', 10, 1),
  ('mission-be-search-03-o1-c1', 'solution', 'Cluster: the whole deployment. Node: one server. Index: like a table. Shard: a slice of an index. Document: like a row.', 20, 2),
  ('mission-be-search-03-o2-c1', 'orientation', 'PostgreSQL is not being replaced -- ask what job it was never designed to do well.', 10, 1),
  ('mission-be-search-03-o2-c1', 'solution', 'Elasticsearch exists for relevance ranking, typo tolerance and search-specific horizontal scale -- purpose-built capabilities, not something bolted onto a general-purpose relational database.', 20, 2),

  ('mission-be-search-04-o1-c1', 'orientation', 'A ''keyword'' mapping means exact-match only -- no analysis, no partial matching.', 10, 1),
  ('mission-be-search-04-o1-c1', 'concept', 'A field mapped as ''text'' gets analyzed and tokenized for full-text search. A field mapped as ''keyword'' is indexed as one exact, unanalyzed value.', 20, 2),
  ('mission-be-search-04-o1-c1', 'solution', '"full_name": { "type": "keyword" } is the bug -- a name meant for full-text search needs the "text" type, not "keyword".', 30, 3),

  ('mission-be-search-05-o1-c1', 'orientation', 'One of these three stages is optional and runs before anything is split into pieces.', 10, 1),
  ('mission-be-search-05-o1-c1', 'solution', 'Character filter, then tokenizer, then token filter -- clean the raw text first, split it into tokens, then reshape each token.', 20, 2),
  ('mission-be-search-05-o2-c1', 'orientation', 'Think about what would break if a query for ''wozniak'' had to match the exact case and could not ignore filler words.', 10, 1),
  ('mission-be-search-05-o2-c1', 'solution', 'Lowercasing lets case differences stop mattering, and stopword removal keeps common words from diluting what actually determines a good match.', 20, 2),

  ('mission-be-search-06-o1-c1', 'orientation', 'Both queries use the exact same tokenizer -- the difference is in what gets fed into it.', 10, 1),
  ('mission-be-search-06-o1-c1', 'concept', 'A hyphen or space between two words usually becomes a token boundary. Remove it, and the tokenizer sees one longer word instead of two shorter ones.', 20, 2),
  ('mission-be-search-06-o1-c1', 'solution', '''Annemarie'' with no separator becomes a single token that matches neither ''anne'' nor ''marie'' in the stored document -- the tokenizer did not fail, it just never saw two separate words.', 30, 3),

  ('mission-be-search-07-o1-c1', 'orientation', 'One of these is analyzed the same way the field was indexed. The other only ever compares raw characters.', 10, 1),
  ('mission-be-search-07-o1-c1', 'solution', 'match tokenizes and ranks; LIKE only checks for one literal substring, with no concept of a token or a score.', 20, 2),
  ('mission-be-search-07-o2-c1', 'orientation', 'Compare what happens to the exact same misspelled input under two different query types.', 10, 1),
  ('mission-be-search-07-o2-c1', 'solution', 'The fuzzy match query still surfaces the correct record for the misspelled input; the exact term query returns nothing for that same input.', 20, 2),

  ('mission-be-search-08-o1-c1', 'orientation', 'One factor is about this document, one is about the whole index, and one is about field size.', 10, 1),
  ('mission-be-search-08-o1-c1', 'solution', 'TF: how often in this document. IDF: how rare across the index. Field length norm: how long the matching field is.', 20, 2),
  ('mission-be-search-08-o2-c1', 'orientation', 'Compare where the match sits in each document, not just whether it matched.', 10, 1),
  ('mission-be-search-08-o2-c1', 'solution', 'A single clean match in a short field (Result A) scores higher than the same term buried once inside a long field (Result B) -- field length and match density both feed the score.', 20, 2),

  ('mission-be-search-09-o1-c1', 'orientation', 'One of these two clauses is asking a question with degrees of correctness. The other has exactly two possible answers.', 10, 1),
  ('mission-be-search-09-o1-c1', 'concept', 'A term query on a status field is a yes/no check -- it has no business affecting how well the document matches the search.', 20, 2),
  ('mission-be-search-09-o1-c1', 'solution', 'The status: active clause belongs in a filter context, not inside must -- it should narrow results without ever touching the score.', 30, 3),

  ('mission-be-search-10-o1-c1', 'orientation', 'A partial string like ''Woz'' is not a complete token the way ''wozniak'' is -- ask what would need to be indexed differently.', 10, 1),
  ('mission-be-search-10-o1-c1', 'solution', 'Indexing every prefix of a term ahead of time -- edge n-grams, or a dedicated completion suggester -- is what turns a partial string into something the index can already match.', 20, 2),

  ('mission-be-search-11-o1-c1', 'orientation', 'The PostgreSQL row and the Elasticsearch document disagree. Ask what process should have reconciled that and did not.', 10, 1),
  ('mission-be-search-11-o1-c1', 'solution', 'No reindex job ever ran against this citizen_id after the initial index -- nothing was watching for the later update.', 20, 2),
  ('mission-be-search-11-o2-c1', 'orientation', 'One system was designed to be durable and authoritative. The other was designed to be fast to search.', 10, 1),
  ('mission-be-search-11-o2-c1', 'solution', 'PostgreSQL is the source of truth; Elasticsearch is a copy that is only as current as whatever keeps it synchronized.', 20, 2),

  ('mission-be-search-12-o1-c1', 'orientation', 'A raw count of tagged records is not the same claim as a share of a specific subset.', 10, 1),
  ('mission-be-search-12-o1-c1', 'concept', '1.8% of the whole registry carrying the tag is unremarkable on its own. The same tag being 34% of one very specific, much smaller subset is not.', 20, 2),
  ('mission-be-search-12-o1-c1', 'solution', 'The tag breakdown is the evidence that actually shows a correlation -- the never-indexed records carry the tag far out of proportion to the registry as a whole.', 30, 3),
  ('mission-be-search-12-o2-c1', 'orientation', 'Nothing about the record itself is broken. Ask what would have had to happen for it to become searchable, and whether that thing ever ran.', 10, 1),
  ('mission-be-search-12-o2-c1', 'solution', 'The index is a copy that only reflects writes something told it about -- an unreindexed record simply never enters it, correct or not.', 20, 2),
  ('mission-be-search-12-o3-c1', 'orientation', 'Rule out the options that only fix today''s problem instead of every future write.', 10, 1),
  ('mission-be-search-12-o3-c1', 'concept', 'A manual backfill only ever catches what has already gone stale. A nightly cron job still leaves up to a day where a real record is invisible to search.', 20, 2),
  ('mission-be-search-12-o3-c1', 'solution', 'Only a change-data-capture or event-driven pipeline reindexes a record the moment it changes, closing the gap for every future write, not just the ones already found.', 30, 3),
  ('mission-be-search-12-o4-c1', 'orientation', 'Connect the three pieces: what the backfill showed, why the gap existed, and what actually closes it for good.', 15, 1),
  ('mission-be-search-12-o4-c1', 'solution', 'The fix is an event-driven reindex pipeline tied to every write. The tag correlation gets filed as an observed, reproducible pattern -- not a conclusion about who or what is behind it.', 25, 2);
